using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PersonalServiceTests
{
    static EntityId Friend=>PersonalCompanionTests.Friend;
    static WorldSession Start(string? policy=null){var lead=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:castle");var friend=lead with{Id=Friend.Value};var setup=NewGameWorldTests.Setup([lead,friend],[]);return new(NewGameWorld.Create(setup.World,setup.Registered,lead.Id,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:policy??PersonalCompanions.PersonalServicePolicy,informationPolicy:PrivateInformation.Policy));}
    static CommandResult Act(WorldSession s,CompanionAction a,long amount=0,string? id=null)=>s.ManageCompanion(new(new(id??"request:personal-service/"+s.Revision),Friend,a,amount),s.PlayerControl,s.Revision);
    static void At(WorldSession s,long t)=>PersonalCompanionTests.Advance(s,t);
    static void Work(WorldSession s,bool open=true){Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Inspect).Code);At(s,8);if(open){var m=s.DiagnosticSnapshot().Companions!.Reports.Single().Message;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m),s.Revision).Code);At(s,9);}}
    static void Pledge(WorldSession s){var r=Act(s,CompanionAction.PledgeService);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    [Fact]public void RoninGainsActualPersonalRetainerWithoutHouseArmyLandMoneyOrGrants(){var s=Start();Work(s);var b=s.DiagnosticSnapshot();Assert.True(s.ConsultPersonalService(Friend,s.PlayerControl,s.Revision).CanConfirm);Pledge(s);var w=s.DiagnosticSnapshot();Assert.Contains(w.ServiceBonds,b=>b.Subject==Friend&&b.Target==s.PlayerControl&&b.From==9&&b.Until==long.MaxValue);Assert.Equal(ContractJson.Write(b.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(b.Grants),ContractJson.Write(w.Grants));Assert.Equal(ContractJson.Write(b.LandRights),ContractJson.Write(w.LandRights));Assert.Empty(w.Units);Assert.Equal(980,NewGameWork.Balance(w,s.PlayerControl));Assert.True(s.PersonalServiceView().Single().Active);}
    [Fact]public void PaidCooperationAndUnreadReportAreNotPersonalService(){var s=Start();Assert.False(s.ConsultPersonalService(Friend,s.PlayerControl,s.Revision).CanConfirm);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);Work(s,false);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Empty(s.PersonalServiceView());}
    [Fact]public void AnotherPersonsExistingRetainerCannotBeConverted(){var setup=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var child=setup.People.Single(p=>p.Lord=="person:shingen");var s=new WorldSession(NewGameWorld.Create(setup,[],"person:shingen",historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.PersonalServicePolicy,informationPolicy:PrivateInformation.Policy));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.False(s.ConsultPersonalService(new(child.Id),s.PlayerControl,s.Revision).CanConfirm);Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(new(new("request:no-existing-retainer"),new(child.Id),CompanionAction.PledgeService),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void WrongActorAndStaleConfirmationCannotCreateService(){var s=Start();Work(s);var i=new CompanionInput(new("request:personal-confirm"),Friend,CompanionAction.PledgeService);var rev=s.Revision;Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(i,Friend,rev).Code);s.SetPaused(false);s.SetPaused(true);Assert.Equal(ResultCode.StateChanged,s.ManageCompanion(i,s.PlayerControl,rev).Code);Assert.Empty(s.PersonalServiceView());}
    [Fact]public void RefusalAndUnpaidHandoutDoNotCreateSupport(){var s=Start();var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Friend?c with{WillObey=false}:c).ToArray();s=new WorldSession(w);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);s=Start();Work(s);At(s,86401);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);Assert.Empty(s.PersonalServiceView());}
    [Fact]public void RepeatedIdAndNewDuplicateDoNotMultiplyBonds(){var s=Start();Work(s);Pledge(s);var q=s.DiagnosticSnapshot().Companions!.Orders.Last().Input;Assert.Equal(ResultCode.AlreadyAccepted,s.ManageCompanion(q,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);Assert.Single(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==Friend);}
    [Fact]public void EndingPaidAgreementDoesNotEraseFormalPersonalBond(){var s=Start();Work(s);Pledge(s);At(s,10);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.EndAgreement).Code);Assert.False(s.CompanionView().Single(c=>c.Person==Friend).Active);Assert.True(s.PersonalServiceView().Single().Active);Assert.Contains(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==Friend&&b.Until==long.MaxValue);}
    [Fact]public void ReleaseEndsOnlyBondAndKeepsUnpaidHandout(){var s=Start();Work(s);Pledge(s);At(s,86401);var b=s.DiagnosticSnapshot();Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.ReleaseService).Code);Assert.False(s.PersonalServiceView().Single().Active);Assert.True(s.CompanionView().Single(c=>c.Person==Friend).Active);Assert.Equal(20,s.CompanionView().Single(c=>c.Person==Friend).Owed);Assert.Equal(980,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ContractJson.Write(b.Memberships),ContractJson.Write(s.DiagnosticSnapshot().Memberships));Assert.Contains(s.DiagnosticSnapshot().ServiceBonds,r=>r.Subject==Friend&&r.Until==86401);}
    [Fact]public void SaveBeforeAndAfterPledgeRestoresFutureWork(){var s=Start();Work(s);s.SetPaused(true);var loaded=Restore(s,"before");Export(s,loaded,"personal-service-before");Assert.Equal(s.ConsultPersonalService(Friend,s.PlayerControl,s.Revision),loaded.ConsultPersonalService(Friend,loaded.PlayerControl,loaded.Revision));Pledge(s);Pledge(loaded);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));loaded=Restore(s,"pledged");Export(s,loaded,"personal-service-pledged");Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Inspect).Code);Assert.Equal(ResultCode.Accepted,Act(loaded,CompanionAction.Inspect).Code);At(s,20);At(loaded,20);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));}
    [Fact]public void ReleasedServiceSaveKeepsEndedHistoryAndDebt(){var s=Start();Work(s);Pledge(s);At(s,86401);Act(s,CompanionAction.ReleaseService);s.SetPaused(true);var loaded=Restore(s,"released");Export(s,loaded,"personal-service-released");Assert.Equal(ContractJson.Write(s.PersonalServiceView()),ContractJson.Write(loaded.PersonalServiceView()));At(s,172801);At(loaded,172801);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(loaded.DiagnosticSnapshot()));Assert.Equal(40,loaded.CompanionView().Single(c=>c.Person==Friend).Owed);}
    [Fact]public void ForgedServiceRelationAndInjectedFeeCannotLoad(){var s=Start();Work(s);Pledge(s);var w=s.DiagnosticSnapshot();w.ServiceBonds=w.ServiceBonds.Select(b=>b.Subject==Friend?b with{Target=new("person:nobunaga")}:b).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Companions=w.Companions! with{Orders=w.Companions!.Orders.Select(q=>q.Input.Action==CompanionAction.PledgeService?q with{Input=q.Input with{Amount=1}}:q).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(PersonalCompanions.Policy)][InlineData(PersonalCompanions.PrivateInspectionPolicy)]public void OldPoliciesKeepBytesAndRejectPersonalService(string policy){var s=Start(policy);Work(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));}
    [Fact]public void BusyAgreementDoesNotAttachAnUnfinishedJobOrAllowImmediateRelease(){var s=Start();Work(s);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Inspect).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.PledgeService).Code);At(s,20);Pledge(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.ReleaseService).Code);At(s,21);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.ReleaseService).Code);}
    [Fact]public void PlayerJoiningHouseDoesNotAutomaticallyMovePersonalRetainersMembership(){var s=Start();Work(s);Pledge(s);var id=new EntityId("request:retinue-service");Assert.Equal(ResultCode.Accepted,s.DecideService(new(id,CareerAction.Apply,Principal:new("person:nobunaga")),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:retinue-service-accept"),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();Assert.Contains(w.Memberships,m=>m.Subject==s.PlayerControl&&m.Target==new EntityId("org:oda"));Assert.DoesNotContain(w.Memberships,m=>m.Subject==Friend);Assert.Contains(w.ServiceBonds,b=>b.Subject==Friend&&b.Target==s.PlayerControl&&b.Until==long.MaxValue);ContractValidation.Validate(w);}
    static WorldSession Restore(WorldSession s,string slot){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"personal-service-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,slot,w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare(slot),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));return host.Current;}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var x in new[]{(s:a,t:"before"),(s:b,t:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+x.t+".json"),ContractJson.Write(x.s.DiagnosticSnapshot()));}
}
